import java.io.*;
import java.util.*;

public class E {

    static long mod = 998244353;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        long n = sc.nextInt();
        long m = sc.nextInt();
        long L = sc.nextInt();
        long R = sc.nextInt();

        if (n % 2 == 1 && m % 2 == 1) {
            System.out.println(pow((R - L + 1) % mod, n * m));
        } else {
            long cnt = R - L + 1;
            if (cnt % 2 == 0) {
                long allbutone = pow(cnt % mod, n * m - 1);
                System.out.println(allbutone * (cnt / 2) % mod);
            } else {
                long k = cnt / 2;
                Matrix mat = new Matrix(k, k + 1, k + 1, k);
                Matrix res = mat.pow(n * m);
                System.out.println(res.a);
            }
        }
    }

    static long pow(long a, long b) {
        if (b == 0) {
            return 1;
        }
        long half = pow(a, b / 2);
        half = half * half % mod;
        if ((b & 1) == 1) {
            half = half * a % mod;
        }
        return half;
    }

    static class Matrix {
        final long a, b, c, d;

        Matrix(long a, long b, long c, long d) {
            this.a = a;
            this.b = b;
            this.c = c;
            this.d = d;
        }

        Matrix mult(Matrix o) {
            return new Matrix(
                (a * o.a + b * o.c) % mod,
                (a * o.b + b * o.d) % mod,
                (c * o.a + d * o.c) % mod,
                (c * o.b + d * o.d) % mod
            );
        }

        Matrix pow(long e) {
            if (e == 0) {
                return new Matrix(1, 0, 0, 1);
            }
            if (e == 1) {
                return this;
            }
            Matrix half = pow(e / 2);
            Matrix square = half.mult(half);
            if ((e & 1) == 1) {
                return square.mult(this);
            } else {
                return square;
            }
        }
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
